/**
 * What the web reminder offer's buttons do. Both save the reminder time and
 * make sure "Reminders by e-mail" is on, through the same writes as Settings
 * (`setReminder`, `patchSettings({ emailNudges })`), so the server and every
 * other device hear it with the next sync; a phone app installed later uses
 * this time too, which is wanted (F3 notes).
 */
import { ApiError, isApiError } from '@/api/errors.js';
import { auth as authApi } from '@/api/endpoints.js';
import { patchSettings, setReminder } from '@/db/mutations.js';
import { t } from '@/i18n/index.js';
import { localTimeZone } from '@/lib/format.js';
import { syncSoon } from '@/sync/store.js';
import { turnOnBrowserPush } from '@/features/auth/session.js';
import { browserReminderTime, emailReminderTime } from './webOffer.js';

export type ReminderOutcome =
  /** Notes in this browser are on, at about `time`. */
  | { kind: 'browser'; time: string }
  /** E-mail reminders are on, to a confirmed address, at about `time`. */
  | { kind: 'email'; time: string }
  /** Saved, and the confirmation link is on its way: e-mails start once it is confirmed. */
  | { kind: 'confirm'; time: string }
  /** The browser refused notifications: nothing was saved. */
  | { kind: 'refused' }
  /** Something did not go through; the offer stays, with this sentence. */
  | { kind: 'failed'; message: string };

/** Saves the reminder time and turns e-mail reminders on, then asks for a sync. */
async function saveReminder(time: string): Promise<void> {
  await setReminder(time, localTimeZone());
  // Sent even when this device already holds "on": the address may have
  // been unsubscribed from an e-mail this device has not heard of, and the
  // learner just asked to be reminded.
  await patchSettings({ emailNudges: true });
  void syncSoon();
}

/**
 * "Remind me in this browser": the browser's permission prompt comes first,
 * from the tap itself (some browsers only ask from a gesture), then the
 * subscription is registered with the server and the time saved.
 */
export async function remindInBrowser(webPushKey: string, now: Date = new Date()): Promise<ReminderOutcome> {
  let outcome: 'on' | 'denied' | 'failed';
  try {
    outcome = await turnOnBrowserPush(webPushKey);
  } catch {
    outcome = 'failed';
  }
  if (outcome === 'denied') return { kind: 'refused' };
  if (outcome === 'failed') return { kind: 'failed', message: t('settings.browserPushFailed') };
  const time = browserReminderTime(now);
  await saveReminder(time);
  return { kind: 'browser', time };
}

/**
 * "E-mail me if I forget" (and "or by e-mail", "E-mail me instead"). With
 * an address not confirmed yet the button says so, and sends the
 * confirmation link through the existing endpoint: the server writes only
 * to confirmed addresses.
 */
export async function remindByEmail(
  verified: boolean,
  refreshUser: () => Promise<void>,
  now: Date = new Date(),
): Promise<ReminderOutcome> {
  const time = emailReminderTime(now);
  try {
    await saveReminder(time);
  } catch {
    return { kind: 'failed', message: t('webReminder.failed') };
  }
  if (verified) return { kind: 'email', time };
  try {
    await authApi.resendVerification();
    return { kind: 'confirm', time };
  } catch (cause) {
    // A link sent a moment ago is still the link to press.
    if (cause instanceof ApiError && cause.code === 'rate_limited') return { kind: 'confirm', time };
    if (cause instanceof ApiError && cause.code === 'already_verified') {
      await refreshUser().catch(() => undefined);
      return { kind: 'email', time };
    }
    if (isApiError(cause, 'offline')) return { kind: 'failed', message: t('error.offline') };
    if (cause instanceof ApiError && cause.code === 'mail_unavailable')
      return { kind: 'failed', message: t('auth.verifyMailUnavailable') };
    return { kind: 'failed', message: t('webReminder.failed') };
  }
}
