import { useEffect, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import type { WebPushSupport } from '@/lib/platform/types.js';
import { useRememberedQuery } from '@/lib/useRememberedQuery.js';
import { useConfig, useWebPushKey } from '@/lib/useConfig.js';
import { accountAddress } from '@/features/auth/hiddenEmail.js';
import { useAuth } from '@/features/auth/session.js';
import { remindByEmail, remindInBrowser, type ReminderOutcome } from './actions.js';
import { markLineShown, markNotNow, markOffered, offersOnSummary, offersOnToday } from './webOffer.js';
import styles from './WebReminderOffer.module.css';

/**
 * How long the offer waits for the server's config (the VAPID key) before
 * deciding which button to show. The config is normally in hand long before
 * a summary; this only bounds a request that never answers, after which the
 * e-mail button, which needs no key, is the honest one.
 */
export const CONFIG_WAIT_MS = 1500;

type Variant = 'browser' | 'email';

/**
 * Which offer this browser gets, decided once: "Remind me in this browser"
 * where a note can arrive (the server has a key, the browser has the Push
 * API and the service worker: Chrome, Edge, Firefox, Safari on a Mac, and on
 * an iPhone only from the Home Screen), the e-mail button everywhere else.
 * Undefined until known, so the card never draws one way and then the other.
 */
function useVariant(wanted: boolean): { variant: Variant | undefined; key: string | undefined } {
  const key = useWebPushKey();
  const answered = useConfig((state) => state.answered);
  const [support, setSupport] = useState<WebPushSupport | undefined>();
  const [waited, setWaited] = useState(false);
  const [held, setHeld] = useState<Variant | undefined>();
  useEffect(() => {
    if (!wanted) return;
    let live = true;
    void platform.webPush.support().then(
      (answer) => {
        if (live) setSupport(answer);
      },
      () => {
        if (live) setSupport('unavailable');
      },
    );
    const timer = setTimeout(() => {
      if (live) setWaited(true);
    }, CONFIG_WAIT_MS);
    return () => {
      live = false;
      clearTimeout(timer);
    };
  }, [wanted]);
  if (held === undefined && wanted && support !== undefined && (answered || waited)) {
    setHeld(key !== undefined && support === 'available' ? 'browser' : 'email');
  }
  return { variant: held, key };
}

/**
 * "Want a nudge tomorrow?" on the first practice day's summary, in a browser
 * tab (marketer's F3, 18 Oct 2026): under any tip, once on this device.
 * Decided once, as the summary opens, and held: marking it shown must not
 * take it away while it is being read.
 */
export function SummaryWebReminder(): React.JSX.Element | null {
  const [wanted, setWanted] = useState(false);
  useEffect(() => {
    let live = true;
    void offersOnSummary().then((answer) => {
      if (live && answer) setWanted(true);
    });
    return () => {
      live = false;
    };
  }, []);
  return wanted ? <WebReminderOffer place="summary" /> : null;
}

/**
 * Today's one later line: the learner came back, still has no reminder time
 * and never pressed "Not now" (`offersOnToday`). Remembered, so a return to
 * Today draws it with the page rather than a moment later, and held once
 * drawn, so saving the time does not take the answer away.
 */
export function TodayWebReminder(): React.JSX.Element | null {
  const due = useRememberedQuery('webReminderLine', offersOnToday, []).value ?? false;
  const [held, setHeld] = useState(false);
  if (due && !held) setHeld(true);
  return held ? <WebReminderOffer place="today" /> : null;
}

/**
 * The offer itself. Never a pop-up: the browser's own permission prompt
 * appears only after the tap.
 */
function WebReminderOffer({ place }: { place: 'summary' | 'today' }): React.JSX.Element | null {
  const user = useAuth((state) => state.user);
  const refreshUser = useAuth((state) => state.refreshUser);
  const wanted = user !== null;
  const { variant, key } = useVariant(wanted);
  const [phase, setPhase] = useState<'idle' | 'busy' | 'asking' | 'closed'>('idle');
  const [outcome, setOutcome] = useState<ReminderOutcome | undefined>();
  // On screen is asked: the summary's once ever, Today's for this day only.
  const shown = wanted && variant !== undefined;
  useEffect(() => {
    if (!shown) return;
    void (place === 'summary' ? markOffered() : markLineShown()).catch(() => undefined);
  }, [shown, place]);

  if (!shown || phase === 'closed') return null;
  const address = accountAddress(user);
  const verified = user.emailVerified;

  const run = (work: () => Promise<ReminderOutcome>, asking = false): void => {
    setPhase(asking ? 'asking' : 'busy');
    void work()
      .catch((): ReminderOutcome => ({ kind: 'failed', message: t('webReminder.failed') }))
      .then((next) => {
        setOutcome(next);
        setPhase('idle');
      });
  };
  const byEmail = (): void => {
    run(() => remindByEmail(verified, refreshUser));
  };
  const inBrowser = (): void => {
    if (key === undefined) return;
    // The browser asks now. Chrome often asks with a small icon in the
    // address bar rather than a box, so the card says where to look.
    run(() => remindInBrowser(key), true);
  };
  const notNow = (): void => {
    setPhase('closed');
    void markNotNow().catch(() => undefined);
  };

  if (outcome !== undefined && outcome.kind !== 'failed' && outcome.kind !== 'refused') {
    const line =
      outcome.kind === 'browser'
        ? t('webReminder.doneBrowser', { time: outcome.time })
        : outcome.kind === 'email'
          ? t('webReminder.doneEmail', { address, time: outcome.time })
          : t('webReminder.confirmSent', { address, time: outcome.time });
    return (
      <section className={styles.offer} data-place={place} aria-label={t('intro.remindTitle')}>
        <span className={styles.mark} data-done="true" aria-hidden="true">
          <Icon name="check" size={18} weight={2.4} />
        </span>
        <p className={styles.done} role="status">
          {line}
        </p>
      </section>
    );
  }

  const busy = phase === 'busy' || phase === 'asking';
  const refused = outcome?.kind === 'refused';
  const failed = outcome?.kind === 'failed' ? outcome.message : undefined;
  const primaryLabel =
    variant === 'browser'
      ? t('webReminder.browser')
      : verified
        ? t('webReminder.email')
        : t('webReminder.confirm');

  return (
    <section className={styles.offer} data-place={place} aria-labelledby={`web-reminder-${place}`}>
      <span className={styles.mark} aria-hidden="true">
        <Icon name="bell" size={18} weight={2} />
      </span>
      <div className={styles.body}>
        <h2 id={`web-reminder-${place}`} className={styles.title}>
          {t('intro.remindTitle')}
        </h2>
        {refused ? (
          <>
            <p className={styles.refused} role="status">
              {t('webReminder.refused')}
            </p>
            <div className={styles.actions}>
              <button type="button" className={styles.primary} disabled={busy} onClick={byEmail}>
                {t('webReminder.emailInstead')}
              </button>
              <button type="button" className={styles.later} onClick={notNow}>
                {t('webReminder.later')}
              </button>
            </div>
          </>
        ) : (
          <>
            <div className={styles.actions}>
              <button
                type="button"
                className={styles.primary}
                disabled={busy}
                aria-busy={busy || undefined}
                onClick={variant === 'browser' ? inBrowser : byEmail}
              >
                {primaryLabel}
              </button>
              <button type="button" className={styles.later} onClick={notNow}>
                {t('webReminder.later')}
              </button>
            </div>
            {variant === 'browser' && (
              <button type="button" className={styles.alt} disabled={busy} onClick={byEmail}>
                {t('webReminder.byEmail')}
              </button>
            )}
          </>
        )}
        {phase === 'asking' && (
          <p className={styles.note} role="status">
            {t('settings.browserPushAsking')}
          </p>
        )}
        {failed !== undefined && phase !== 'asking' && (
          <p className={styles.failed} role="status">
            {failed}
          </p>
        )}
        <p className={styles.note}>{t('webReminder.note')}</p>
      </div>
    </section>
  );
}
